// Visual landmarks are decorative; the adjacent text and diagrams carry the lesson.
$$('.topic-panel').forEach((panel,index)=>{if(!index)return;const candidates=[...panel.querySelectorAll('.reading-card')];candidates.forEach((card,i)=>{if(card.classList.contains('distance-card')||card.classList.contains('interval-experiment'))return;const art=document.createElement('div');art.className='section-art '+(index===2?'art-scale':index===3?'art-chord':i%3===1?'art-scale':i%3===2?'art-chord':'');art.setAttribute('aria-hidden','true');const heading=card.querySelector(':scope > h2');if(heading)heading.before(art);else card.prepend(art)})});
// The launcher is icon-only. Drag the icon or the opened panel's header.
$('#pianoToggle').innerHTML='<svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><rect x="3" y="5" width="26" height="22" rx="3" stroke="currentColor" stroke-width="1.6"/><path d="M9.5 6v20M16 6v20M22.5 6v20" stroke="currentColor" stroke-width="1.2"/><path d="M8 6h3v11H8zm6.5 0h3v11h-3zm6.5 0h3v11h-3z" fill="currentColor"/></svg>';
$('#pianoToggle').setAttribute('aria-label','展开或收起小钢琴；拖动可移动位置');$('#pianoToggle').title='小钢琴 · 点击展开，拖动移动';
let manuallyPlaced=false,suppressPianoClick=false,drag=null;
function constrainDock(){if(!manuallyPlaced)return;const r=dock.getBoundingClientRect(),padding=8;dock.style.left=Math.max(padding,Math.min(r.left,innerWidth-r.width-padding))+'px';dock.style.top=Math.max(padding,Math.min(r.top,innerHeight-r.height-padding))+'px';dock.style.right='auto';dock.style.bottom='auto'}
const themedOpenPiano=openPiano;openPiano=function(open){dock.classList.toggle('piano-open',open);themedOpenPiano(open);requestAnimationFrame(constrainDock)};
function beginDrag(e){if(e.button!==0||e.target.closest('.piano-toolbar button'))return;const r=dock.getBoundingClientRect();drag={id:e.pointerId,x:e.clientX,y:e.clientY,left:r.left,top:r.top,moved:false,target:e.currentTarget};e.currentTarget.setPointerCapture(e.pointerId)}
function moveDrag(e){if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.moved&&Math.hypot(dx,dy)<5)return;drag.moved=true;manuallyPlaced=true;e.preventDefault();dock.classList.add('dragging');dock.style.left=drag.left+dx+'px';dock.style.top=drag.top+dy+'px';dock.style.right='auto';dock.style.bottom='auto';constrainDock()}
function endDrag(e){if(!drag||drag.id!==e.pointerId)return;if(drag.moved){suppressPianoClick=true;setTimeout(()=>suppressPianoClick=false,0)}drag=null;dock.classList.remove('dragging')}
[$('#pianoToggle'),$('.piano-toolbar')].forEach(handle=>{handle.addEventListener('pointerdown',beginDrag);handle.addEventListener('pointermove',moveDrag);['pointerup','pointercancel','lostpointercapture'].forEach(type=>handle.addEventListener(type,endDrag))});
$('#pianoToggle').addEventListener('click',e=>{if(suppressPianoClick){e.preventDefault();e.stopImmediatePropagation()}},true);window.addEventListener('resize',constrainDock);
